const $=s=>document.querySelector(s);
export const DEFAULT_SETTINGS=Object.freeze({quality:'light',sensitivity:1,fov:65,invert:false,hud:true,hints:true});
export function sanitizeSettings(value={}){if(!value||typeof value!=='object')value={};return {quality:value.quality==='standard'?'standard':'light',sensitivity:Math.min(2,Math.max(.4,Number(value.sensitivity)||1)),fov:Math.min(85,Math.max(55,Number(value.fov)||65)),invert:value.invert===true,hud:value.hud!==false,hints:value.hints!==false};}
export class WalkUI{
 constructor(callbacks,touch){this.callbacks=callbacks;this.touch=touch;this.state='loading';this.played=false;this.dialog=$('#pause-dialog');this.dialogOrigin='title';this.settings={...DEFAULT_SETTINGS};this.hintUntil=0;this.toastTimer=0;try{this.settings=sanitizeSettings(JSON.parse(localStorage.getItem('kamakura-ui-v16')||'{}'));}catch{}this.bind();this.syncSettings();}
 get playing(){return this.state==='playing';}
 mode(state){this.state=state;document.body.dataset.state=state;$('#title-screen').classList.toggle('hidden',state!=='title');$('#hud').classList.toggle('hidden',state!=='playing');$('#touch-controls').classList.toggle('hidden',state!=='playing'||!this.touch);this.callbacks.mode(state);}
 ready(){this.mode('title');$('#loading').classList.add('hidden');}
 progress(event){if(event?.total){const p=Math.max(0,Math.min(100,Math.round(event.loaded/event.total*100)));$('#load-bar').style.width=p+'%';$('#progress-track').setAttribute('aria-valuenow',p);$('#load-text').textContent=`3Dモデルを読み込んでいます · ${p}%`;}else{$('#load-text').textContent='3Dモデルを読み込んでいます';$('#progress-track').removeAttribute('aria-valuenow');$('#progress-track').classList.add('indeterminate');}}
 preparing(){$('#load-title').textContent='もうすぐ、庭へ';$('#load-text').textContent='表示を整えています';$('#progress-track').classList.remove('indeterminate');$('#load-bar').style.width='100%';}
 error(error){this.mode('error');if(this.dialog.open)this.dialog.close();$('#loading').classList.remove('hidden');$('#loading').classList.add('error-state');$('#load-title').textContent='風景をひらけませんでした';$('#load-text').textContent=/webgl/i.test(String(error))?'このブラウザでは3D表示を開始できませんでした。WebGL2対応のブラウザと、グラフィック設定をご確認ください。':'モデルの読み込みが途中で止まりました。接続を確認して、もう一度読み込んでください。';$('#load-note').textContent='保存済みの設定や元のモデルは変更されません';$('#progress-track').classList.add('hidden');$('#retry').classList.remove('hidden');$('#retry').focus({preventScroll:true});}
 play(lock=true){if(this.state==='loading'||this.state==='error')return;if(this.dialog.open)this.dialog.close();this.played=true;$('#start-label').textContent='散策をつづける';this.mode('playing');this.hintUntil=performance.now()+10000;if(lock&&!this.touch)this.callbacks.lock();this.pointerChanged();}
 open(panel='rest'){if(this.state==='loading'||this.state==='error')return;if(!this.dialog.open){this.dialogOrigin=this.state==='playing'?'playing':'title';this.mode(this.dialogOrigin==='playing'?'paused':'title');if(document.pointerLockElement)document.exitPointerLock();this.dialog.showModal();}this.panel(panel);}
 panel(panel){for(const id of ['rest','controls','settings'])$('#panel-'+id).classList.toggle('hidden',id!==panel);for(const b of document.querySelectorAll('[data-panel]')){const active=b.dataset.panel===panel;b.classList.toggle('active',active);b.setAttribute('aria-current',active?'page':'false');}$('#dialog-title').textContent=panel==='controls'?'歩き方':panel==='settings'?'設定':'ひと休み';$('#dialog-kicker').textContent=this.dialogOrigin==='playing'?'散策をひと休み':'残火の鎌倉';$('#resume').classList.toggle('hidden',this.dialogOrigin!=='playing');$('#reset').classList.toggle('hidden',this.dialogOrigin!=='playing');$('#to-title').classList.toggle('hidden',this.dialogOrigin!=='playing');$('.nav-divider').classList.toggle('hidden',this.dialogOrigin!=='playing');$('#dialog-footer-text').textContent=this.dialogOrigin==='playing'?'移動は一時停止しています':'庭を歩く、小さな散策シーン';}
 close(lock=false){if(!this.dialog.open)return;this.dialog.close();if(this.dialogOrigin==='playing')this.play(lock);else this.mode('title');}
 title(){if(this.dialog.open)this.dialog.close();this.mode('title');if(document.pointerLockElement)document.exitPointerLock();$('#start').focus({preventScroll:true});}
 pause(){if(this.playing)this.open('rest');}
 notify(text,ms=2000){const el=$('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(this.toastTimer);this.toastTimer=setTimeout(()=>el.classList.remove('visible'),ms);}
 tick(now){$('#control-hint').classList.toggle('is-faded',!this.settings.hints||now>this.hintUntil);}
 pointerChanged(){$('#look').classList.toggle('hidden',this.touch||!!document.pointerLockElement||!this.playing);}
 changeSettings(){this.settings=sanitizeSettings({quality:$('#quality').value,sensitivity:$('#sensitivity').value,fov:$('#fov').value,invert:$('#invert').checked,hud:$('#show-hud').checked,hints:$('#show-hints').checked});this.syncSettings();try{localStorage.setItem('kamakura-ui-v16',JSON.stringify(this.settings));}catch{}this.callbacks.settings(this.settings);}
 syncSettings(){const s=this.settings;$('#quality').value=s.quality;$('#sensitivity').value=s.sensitivity;$('#sensitivity-value').textContent=s.sensitivity.toFixed(1);$('#fov').value=s.fov;$('#fov-value').textContent=s.fov+'°';$('#invert').checked=s.invert;$('#show-hud').checked=s.hud;$('#show-hints').checked=s.hints;document.body.classList.toggle('hud-hidden',!s.hud);}
 toggleHUD(){this.settings.hud=!this.settings.hud;this.syncSettings();this.changeSettings();this.notify(this.settings.hud?'画面表示を戻しました':'画面表示を隠しました。Hで戻せます');}
 bind(){$('#start').onclick=()=>this.play();$('#menu-button').onclick=()=>this.open();$('#resume').onclick=()=>this.close(true);$('#dialog-close').onclick=()=>this.close();$('#look').onclick=()=>this.callbacks.lock();$('#retry').onclick=()=>location.reload();$('#reset').onclick=()=>{this.callbacks.reset();this.notify('出発点に戻りました');};$('#to-title').onclick=()=>this.title();for(const b of document.querySelectorAll('[data-open]'))b.onclick=()=>this.open(b.dataset.open);for(const b of document.querySelectorAll('[data-panel]'))b.onclick=()=>this.panel(b.dataset.panel);for(const id of ['quality','sensitivity','fov','invert','show-hud','show-hints'])$('#'+id).addEventListener(id==='sensitivity'||id==='fov'?'input':'change',()=>this.changeSettings());$('#defaults').onclick=()=>{this.settings={...DEFAULT_SETTINGS};this.syncSettings();this.changeSettings();this.notify('設定を初期値に戻しました');};this.dialog.addEventListener('cancel',e=>{e.preventDefault();this.close();});}
}
